{"file_path":"tests/test_spec.py","content":""""Regression tests for the public behaviour specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_and_handles_empty():
    groups = {"small": [session("a", 1, True)],
              "large": [session(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (10, 9)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_session_log_skips_lines_and_parses_values():
    lines = ["\n", "  # comment, with, commas", "  ", " a , 2 , 1 ",
             "b, -1, 0", "c, 0,   "]
    assert parse_session_log(lines) == [session("a", 2, True), session("b", -1, False),
                                        session("c", 0, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "a,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [session("a", 1, True), session("b", 2, True),
              session("c", 1, True), session("a", 2, None),
              session("b", 1, False)]
    assert dedupe_sessions(events) == [session("b", 1, False), session("c", 1, True),
                                       session("a", 2, None)]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_gaps_and_limits_range():
    events = [session("a", 0, True), session("b", 1, True), session("c", 1, True),
              session("d", 2, None), session("e", 3, False), session("f", 5, True)]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"empty": [], "a": [session("a", 1, True)],
              "b": [session("b", 4, True), session("c", 5, False),
                    session("d", 5, None), session("e", 5, False),
                    session("f", 5, False)]}
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary(groups, 20)["recent"] == 2
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_orders_names_and_represents_empty():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1, 0], 0),
                                               ([1, 2, 0, 3, 4, 5, -1, 6], 3)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
